(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;root.PlayroomMiniSplitDeck=api;})(globalThis,function(){
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function face({rank='',suit='',hidden=false,main,suitOnly=false,crown=false}={}){
  if(hidden||typeof main==='string')return null;
  const mark=`<g fill="currentColor" font-family="system-ui,sans-serif" font-weight="700"><text x="50" y="100" text-anchor="middle" font-size="84">${esc(suit)}</text></g>`;
  if(suitOnly)return `<svg class="piece-art mini-split-face suit-only" viewBox="0 0 100 140" aria-hidden="true" focusable="false">${mark}</svg>`;
  return `<svg class="piece-art mini-split-face" viewBox="0 0 100 140" preserveAspectRatio="xMidYMid meet" aria-hidden="true" focusable="false"><g fill="currentColor" font-family="system-ui,sans-serif"><text x="${String(rank).length>1?10:16.25}" y="36.2" font-size="${String(rank).length>2?Math.max(12,Math.floor(90/String(rank).length)):String(rank).length===2?28:30}" font-weight="700">${esc(rank)}</text>${crown?'<path d="m31.25 47.1 8.75 8.45 10-15.69 10 15.69 8.75-8.45-5 22.93h-27.5Z" fill="var(--color-material-card-crown,#c9a44f)"/>':''}<text x="50" y="${crown?122:100}" text-anchor="middle" font-size="${crown?60:84}" font-weight="700">${esc(suit)}</text></g></svg>`;
 }
 return Object.freeze({face});
});

globalThis.PlayroomPackResources = {"locales":{"ru":{"durak.meta.name":"Дурак","durak.meta.description":"Простой, подкидной и переводной дурак на 2–6 игроков.","durak.meta.wins":"победы","durak.meta.victory":"Победа","durak.meta.hand-count":"Карт в руке","durak.meta.classic":"Выбранные правила","durak.actions.exchange":"Обменять младший козырь","durak.actions.confirm":"Подтвердить заход","durak.actions.undo":"Убрать последнюю карту","durak.actions.take":"Беру","durak.actions.end-throw":"Закончить подкидывать","durak.actions.beaten":"Бито","durak.actions.pass":"Бито / пас","durak.actions.open":"В заход: {card}","durak.actions.attack":"Подкинуть {card}","durak.actions.defend":"{card} бьёт {attack}","durak.actions.transfer":"Перевести {card}","durak.card.red-joker":"Красный джокер","durak.card.black-joker":"Чёрный джокер","durak.card.face":"{rank}{suit}","durak.rank.11":"В","durak.rank.12":"Д","durak.rank.13":"К","durak.rank.14":"Т","durak.events.taken":"{player} забирает {count} карт","durak.events.discarded":"Бито","durak.events.drawn":"{player} добрал {count} карт","durak.events.exchanged":"{player} обменял младший козырь","durak.events.confirmed":"{player} подтвердил заход","durak.events.passed":"{player}: пас","durak.events.taking":"{player}: беру","durak.events.transferred":"{player} переводит: {card}","durak.events.attacked":"{player} атакует: {card}","durak.events.defended":"{player}: {card} бьёт {attack}","durak.events.all-out":"Ничья: все игроки вышли","durak.events.first-out":"Первый выход: {players}","durak.events.last-fool":"{player} остался в дураках","durak.speech.pass":"Пас","durak.speech.take":"Беру","durak.rank.15":"Дж","durak.suit.hearts":"черви","durak.suit.diamonds":"бубны","durak.suit.clubs":"трефы","durak.suit.spades":"пики","durak.view.joker-help":"{card}. Сила зависит от выбранного набора правил.","durak.view.card-help":"{rank} {suit}. {rule}","durak.view.trump-rule":"Это козырь: он бьёт любую некозырную карту и младшие козыри.","durak.view.suit-rule":"Эта карта бьёт младшие карты той же масти. Отбить её можно старшей картой той же масти или козырем.","durak.view.stock":"Осталось в колоде","durak.view.trump-help":"Козырная масть: {suit}. Козырь бьёт любую некозырную карту; козырь можно побить только старшим козырем.","durak.view.trump":"Козырь","durak.view.discard":"Бито","durak.view.defend-hint":". Подтвердите защиту выбранной картой.","durak.view.uncovered":"Карта не побита","durak.view.taking":"Берёт","durak.view.defender":"Защита","durak.view.attacker":"Атака","durak.view.thrower":"Подкидывает","durak.view.hand-hint":"Коснитесь карты · свайп вверх — сыграть","durak.modes.classic":"Вариант боя, колода, джокеры и завершение выбираются отдельно. Атака, защиты и подкидывания образуют один ход до взятия или отбоя.","durak.rules.1":"Цель\nИзбавьтесь от карт после окончания колоды. В обычном режиме последний с картами остаётся дураком. Ранний выход даёт более высокое место; вышедшие в одном розыгрыше делят место.","durak.rules.2":"Раздача и козырь\nПодкидной / переводной — 6\nПростой — 5\nОстаток — колода для добора. Открытая карта под ней определяет козырь и берётся последней. Жёлтый жетон показывает козырь и после окончания колоды.\nПорядок: младшая цифра → 10 → валет → дама → король → туз. В колоде 36 младшая — 6, в 52 и 54 — 2.\nПо умолчанию начинает владелец младшего козыря; нет козырей — первый участник. Начинающего можно назначить в комнате.","durak.rules.3":"Атака и защита\nАтакующий выкладывает карту. Следующий игрок защищается.\nПобейте карту старшей той же масти. Некозырную можно побить любым козырем; козырь — старшим козырем. Исключения джокеров описаны ниже.\nОтбейте все карты либо выберите «Взять».\nРозыгрыш заканчивается после завершения подкидываний. При успешной защите «Бито» отправляет карты в отбой — закрытую стопку, которая больше не играет. При взятии защитник забирает карты по правилам варианта.","durak.rules.4":"Подкидной\nНачните 1 картой. Затем все, кроме защитника, могут по очереди подкидывать достоинства, уже лежащие на столе, включая карты защиты. На 7, побитую дамой, можно подкинуть 7 или даму любой масти.\nЛимит атак — не больше 6 и числа карт защитника в начале защиты.\nПосле «Взять» подкидывание продолжается в пределах лимита. Защитник берёт весь стол, включая побитые карты.","durak.rules.5":"Простой\nЗаход собирается заранее. Лимит — не больше 5 и числа карт защитника.\n1 карта — Любая.\n3 карты — 2 одного достоинства + любая 3-я.\n5 карт — 2 пары + любая 5-я. 4 одного достоинства считаются 2 парами.\nПосле подтверждения подкидывания нет. При неудачной защите берутся только непобитые карты; побитые пары уходят в отбой.","durak.rules.6":"Переводной\nДо первой побитой карты добавьте карту того же достоинства, что все атакующие: вся атака переходит следующему игроку.\nУ нового защитника должно хватать карт на всю атаку; максимум — 6.\nПосле перевода действует подкидывание.\nЕсли хотя бы 1 карта побита, перевод запрещён.","durak.rules.7":"Добор и следующий заход\nДоберите до 5 или 6 карт по варианту, пока есть колода.\nПервым берёт первоначальный атакующий, затем остальные по кругу. Последний защитник берёт последним, даже после перевода.\nОтбился — Защитник.\nВзял — Следующий после защитника.\nПустая рука означает выход только после розыгрыша и добора, когда колода пуста.","durak.rules.8":"Обмен козыря\nПеред первой выкладкой нового захода можно обменять младший козырь руки на открытую карту под колодой: 6 для колоды 36, 2 для 52 или 54.\nОбмен доступен, пока открытый козырь в колоде. Сам обмен не завершает ход.","durak.rules.9":"Джокеры · колода 54\nПо цвету — Джокер цвета козыря бьёт любую обычную карту и другого джокера. Второй джокер бьёт только некозырные карты своего цвета; его бьёт любой козырь или джокер цвета козыря.\nУниверсальные — Любой джокер бьёт любую обычную карту. Красный джокер бьёт чёрного. Обычные карты джокеров не бьют.\nКрасные масти — черви и бубны; чёрные — пики и трефы.","durak.rules.10":"Завершение\nДо победителя — Первый выход.\nДо последнего — 1 участник с картами.\nПосле одного розыгрыша карты закончились у всех — ничья.\nПростой вариант и расширенные колоды используют описанные здесь домашние правила.","durak.tutorial.table":"Выберите место на столе: атакуйте или побейте карту соперника.","durak.tutorial.card":"Выберите карту для хода.","durak.tutorial.take":"Нажмите, чтобы забрать карты со стола.","durak.tutorial.done":"Завершите атаку кнопкой «Бито».","durak.tutorial.attack":"Положите карту для атаки или подкиньте её.","durak.tutorial.defend":"Выберите карту на столе, которую хотите побить.","durak.tutorial.transfer":"Переведите атаку на следующего игрока.","durak.tutorial.confirm":"Подтвердите выложенные карты.","durak.tutorial.undo":"Можно отменить ещё не подтверждённую выкладку.","durak.tutorial.exchange":"Обменяйте подходящую карту на козырь из-под колоды.","durak.book.text.1":"Избавьтесь от карт после окончания колоды. В обычном режиме последний с картами остаётся дураком. Ранний выход даёт более высокое место; вышедшие в одном розыгрыше делят место.","durak.book.text.2":"Вариант","durak.book.text.3":"Карт в руке","durak.book.text.4":"Подкидной / переводной","durak.book.text.5":"6","durak.book.text.6":"Простой","durak.book.text.7":"5","durak.book.text.8":"Остаток — колода для добора. Открытая карта под ней определяет козырь и берётся последней. Жёлтый жетон показывает козырь и после окончания колоды.","durak.book.text.9":"Порядок: младшая цифра → 10 → валет → дама → король → туз. В колоде 36 младшая — 6, в 52 и 54 — 2.","durak.book.text.10":"По умолчанию начинает владелец младшего козыря; нет козырей — первый участник. Начинающего можно назначить в комнате.","durak.book.text.11":"Атакующий выкладывает карту. Следующий игрок защищается.","durak.book.text.12":"Побейте карту старшей той же масти. Некозырную можно побить любым козырем; козырь — старшим козырем. Исключения джокеров описаны ниже.","durak.book.text.13":"Отбейте все карты либо выберите «Взять».","durak.book.text.14":"Розыгрыш заканчивается после завершения подкидываний. При успешной защите «Бито» отправляет карты в отбой — закрытую стопку, которая больше не играет. При взятии защитник забирает карты по правилам варианта.","durak.book.text.15":"Начните 1 картой. Затем все, кроме защитника, могут по очереди подкидывать достоинства, уже лежащие на столе, включая карты защиты. На 7, побитую дамой, можно подкинуть 7 или даму любой масти.","durak.book.text.16":"Лимит атак — не больше 6 и числа карт защитника в начале защиты.","durak.book.text.17":"После «Взять» подкидывание продолжается в пределах лимита. Защитник берёт весь стол, включая побитые карты.","durak.book.text.18":"Заход собирается заранее. Лимит — не больше 5 и числа карт защитника.","durak.book.text.19":"Размер","durak.book.text.20":"Состав","durak.book.text.21":"1 карта","durak.book.text.22":"Любая.","durak.book.text.23":"3 карты","durak.book.text.24":"2 одного достоинства + любая 3-я.","durak.book.text.25":"5 карт","durak.book.text.26":"2 пары + любая 5-я. 4 одного достоинства считаются 2 парами.","durak.book.text.27":"После подтверждения подкидывания нет. При неудачной защите берутся только непобитые карты; побитые пары уходят в отбой.","durak.book.text.28":"До первой побитой карты добавьте карту того же достоинства, что все атакующие: вся атака переходит следующему игроку.","durak.book.text.29":"У нового защитника должно хватать карт на всю атаку; максимум — 6.","durak.book.text.30":"После перевода действует подкидывание.","durak.book.text.31":"Если хотя бы 1 карта побита, перевод запрещён.","durak.book.text.32":"Доберите до 5 или 6 карт по варианту, пока есть колода.","durak.book.text.33":"Первым берёт первоначальный атакующий, затем остальные по кругу. Последний защитник берёт последним, даже после перевода.","durak.book.text.34":"Защита","durak.book.text.35":"Кто атакует дальше","durak.book.text.36":"Отбился","durak.book.text.37":"Защитник.","durak.book.text.38":"Взял","durak.book.text.39":"Следующий п